/** static void Task_GiveExpToMon(u8 taskId) */
export function Task_GiveExpToMon(taskId: any): any {
  let monId: any = (gTasks[taskId].tExpTask_monId);
      let battler: any = gTasks[taskId].tExpTask_battler;
      let gainedExp: any = gTasks[taskId].tExpTask_gainedExp;

      if (IsDoubleBattle() == TRUE || monId != gBattlerPartyIndexes[battler])  
      {
          let mon: any =gPlayerParty[monId];
          let species: any = GetMonData(mon, MON_DATA_SPECIES);
          let level: any = GetMonData(mon, MON_DATA_LEVEL);
          let currExp: any = GetMonData(mon, MON_DATA_EXP);
          let nextLvlExp: any = gExperienceTables[gSpeciesInfo[species].growthRate][level + 1];

          if (currExp + gainedExp >= nextLvlExp)
          {
              let savedActiveBattler: any = null;

              SetMonData(mon, MON_DATA_EXP,nextLvlExp);
              CalculateMonStats(mon);
              gainedExp -= nextLvlExp - currExp;
              savedActiveBattler = gActiveBattler;
              gActiveBattler = battler;
              BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, (11), gainedExp);
              gActiveBattler = savedActiveBattler;

              if (IsDoubleBattle() == TRUE
               && ((monId) == gBattlerPartyIndexes[battler] || (monId) == gBattlerPartyIndexes[BATTLE_PARTNER(battler)]))
                  gTasks[taskId].func = Task_LaunchLvlUpAnim;
              else
                  gTasks[taskId].func = DestroyExpTaskAndCompleteOnInactiveTextPrinter;
          }
          else
          {
              currExp += gainedExp;
              SetMonData(mon, MON_DATA_EXP,currExp);
              gBattlerControllerFuncs[battler] = CompleteOnInactiveTextPrinter;
              DestroyTask(taskId);
          }
      }
      else
      {
          gTasks[taskId].func = Task_PrepareToGiveExpWithExpBar;
      }
}

/** static void Task_PrepareToGiveExpWithExpBar(u8 taskId) */
export function Task_PrepareToGiveExpWithExpBar(taskId: any): any {
  let monIndex: any = gTasks[taskId].tExpTask_monId;
      let gainedExp: any = gTasks[taskId].tExpTask_gainedExp;
      let battler: any = gTasks[taskId].tExpTask_battler;
      let mon: any =gPlayerParty[monIndex];
      let level: any = GetMonData(mon, MON_DATA_LEVEL);
      let species: any = GetMonData(mon, MON_DATA_SPECIES);
      let exp: any = GetMonData(mon, MON_DATA_EXP);
      let currLvlExp: any = gExperienceTables[gSpeciesInfo[species].growthRate][level];
      let expToNextLvl: any = null;

      exp -= currLvlExp;
      expToNextLvl = gExperienceTables[gSpeciesInfo[species].growthRate][level + 1] - currLvlExp;
      SetBattleBarStruct(battler, gHealthboxSpriteIds[battler], expToNextLvl, exp, -gainedExp);
      PlaySE((33));
      gTasks[taskId].func = Task_GiveExpWithExpBar;
}

/** static void Task_GiveExpWithExpBar(u8 taskId) */
export function Task_GiveExpWithExpBar(taskId: any): any {
  if (gTasks[taskId].tExpTask_frames < 13)
      {
          gTasks[taskId].tExpTask_frames++;
      }
      else
      {
          let monId: any = gTasks[taskId].tExpTask_monId;
          let gainedExp: any = gTasks[taskId].tExpTask_gainedExp;
          let battler: any = gTasks[taskId].tExpTask_battler;
          let newExpPoints: any = null;

          newExpPoints = MoveBattleBar(battler, gHealthboxSpriteIds[battler], EXP_BAR, 0);
          SetHealthboxSpriteVisible(gHealthboxSpriteIds[battler]);
          if (newExpPoints == -1)  
          {
              let level: any = null;
              let currExp: any = null;
              let species: any = null;
              let expOnNextLvl: any = null;

              m4aSongNumStop((33));
              level = GetMonData(gPlayerParty[monId], MON_DATA_LEVEL);
              currExp = GetMonData(gPlayerParty[monId], MON_DATA_EXP);
              species = GetMonData(gPlayerParty[monId], MON_DATA_SPECIES);
              expOnNextLvl = gExperienceTables[gSpeciesInfo[species].growthRate][level + 1];

              if (currExp + gainedExp >= expOnNextLvl)
              {
                  let savedActiveBattler: any = null;

                  SetMonData(gPlayerParty[monId], MON_DATA_EXP,expOnNextLvl);
                  CalculateMonStats(gPlayerParty[monId]);
                  gainedExp -= expOnNextLvl - currExp;
                  savedActiveBattler = gActiveBattler;
                  gActiveBattler = battler;
                  BtlController_EmitTwoReturnValues(B_COMM_TO_ENGINE, (11), gainedExp);
                  gActiveBattler = savedActiveBattler;
                  gTasks[taskId].func = Task_LaunchLvlUpAnim;
              }
              else
              {
                  currExp += gainedExp;
                  SetMonData(gPlayerParty[monId], MON_DATA_EXP,currExp);
                  gBattlerControllerFuncs[battler] = CompleteOnInactiveTextPrinter;
                  DestroyTask(taskId);
              }
          }
      }
}

/** static void Task_LaunchLvlUpAnim(u8 taskId) */
