/** static void PlayerHandleDMA3Transfer(void) */
export function PlayerHandleDMA3Transfer(): any {
  let dstArg: any = gBattleBufferA[gActiveBattler][1]
              | (gBattleBufferA[gActiveBattler][2] << 8)
              | (gBattleBufferA[gActiveBattler][3] << 16)
              | (gBattleBufferA[gActiveBattler][4] << 24);
      let sizeArg: any = gBattleBufferA[gActiveBattler][5] | (gBattleBufferA[gActiveBattler][6] << 8);

      let src: any =gBattleBufferA[gActiveBattler][7];
      let dst: any = (dstArg);
      let size: any = sizeArg;

      while (1)
      {
          if (size <= 0x1000)
          {
              DmaCopy16(3, src, dst, size);
              break;
          }
          DmaCopy16(3, src, dst, 0x1000);
          src += 0x1000;
          dst += 0x1000;
          size -= 0x1000;
      }
      PlayerBufferExecCompleted();
}

