/** static void Task_StartSendOutAnim(u8 taskId) */
export function Task_StartSendOutAnim(taskId: any): any {
  if (gTasks[taskId].tStartTimer < 31)
      {
          gTasks[taskId].tStartTimer++;
      }
      else
      {
          let savedActiveBattler: any = gActiveBattler;

          gActiveBattler = gTasks[taskId].tBattlerId;
          if (!IsDoubleBattle() || (gBattleTypeFlags & ((1 << 6))))
          {
              gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
              StartSendOutAnim(gActiveBattler, FALSE);
          }
          else
          {
              gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
              StartSendOutAnim(gActiveBattler, FALSE);
              gActiveBattler ^= (2);
              gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
              BattleLoadPlayerMonSpriteGfx(gPlayerParty[gBattlerPartyIndexes[gActiveBattler]], gActiveBattler);
              StartSendOutAnim(gActiveBattler, FALSE);
              gActiveBattler ^= (2);
          }
          gBattlerControllerFuncs[gActiveBattler] = Intro_TryShinyAnimShowHealthbox;
          gActiveBattler = savedActiveBattler;
          DestroyTask(taskId);
      }
}

